pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmt, uint256 withdrawAmt, address actor) public {
        vm.assume(actor != address(0));
        depositAmt = bound(depositAmt, 1, type(uint128).max);
        withdrawAmt = bound(withdrawAmt, 0, depositAmt);
        vm.deal(actor, depositAmt);
        vm.prank(actor);
        c.deposit{value: depositAmt}();
        vm.prank(actor);
        c.withdraw(withdrawAmt);
        // Rule: after withdrawing withdrawAmt, the recorded balance is depositAmt - withdrawAmt,
        // so withdrawing the full depositAmt again must fail.
        bool ok;
        vm.prank(actor);
        try c.withdraw(depositAmt) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}

