pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Actor actor;

    function setUp() public {
        c = new C();
        actor = new Actor(c);
    }

    function testFuzz_property(uint256 d, uint256 a) public {
        d = bound(d, 1, 1e30);
        a = bound(a, 0, d);

        // fund the actor so it can deposit; actor accepts ether so c's transfer to it succeeds
        vm.deal(address(actor), d);
        actor.deposit(d);

        // withdrawal succeeds for any a <= d
        actor.withdraw(a);

        // Rule: withdrawing only removes the withdrawn amount — recorded balance is d - a.
        assertTrue(c.balances(address(actor)) == d - a);
    }
}

contract Actor {
    C c;
    constructor(C c_) { c = c_; }
    receive() external payable {}
    function deposit(uint256 amt) external payable { c.deposit{value: amt}(); }
    function withdraw(uint256 amt) external { c.withdraw(amt); }
}

