pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 v, uint256 amount, address actor) public {
        vm.assume(actor != address(c) && actor != address(this));
        v = bound(v, 1, 1000 ether);
        amount = bound(amount, 1, v);

        // deposit v from actor
        vm.deal(actor, v);
        vm.prank(actor);
        c.deposit{value: v}();
        assert(address(c).balance == v);

        // first withdrawal of `amount`
        vm.prank(actor);
        c.withdraw(amount);

        // drain the remainder: in the correct contract the ledger equals
        // v - amount, so withdrawing exactly the contract balance succeeds
        // and empties it. In the buggy contract the ledger is v - amount/2,
        // which exceeds address(c).balance, so this call reverts and the
        // contract cannot be emptied.
        vm.prank(actor);
        c.withdraw(address(c).balance);

        assertTrue(address(c).balance == 0);
    }
}

